import {STORAGE,LIBRARY,LIMIT,SLOTS,uid,clone,active,newDoc,variant,normalize,slotsFor,compatible,selectedItem,summary,differences,boardNodes,toggleNode,skillLevels,shareCode,readShare} from './model.mjs';
import {boundedInt,pairs,petLevels,collectionRows,recordStatus,detailForSkill,buildChecks,compareSystems,groupSummaryRows} from './review-model.mjs?v=3';

const $=s=>document.querySelector(s),root=$('#app'),dialog=$('#dialog');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n);
const glyphs={shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7Z',sword:'m4 20 12-12m-9 3 6 6M13 7l4-4h4v4l-4 4M3 17l4 4',gem:'m3 8 4-5h10l4 5-9 13Z M3 8h18M7 3l5 18 5-18',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16',book:'M12 5C9 2 3 3 3 3v16s6-1 9 2c3-3 9-2 9-2V3s-6-1-9 2Zm0 0v16',save:'M4 3h13l4 4v14H3V3Zm3 0v7h10V3M7 21v-7h10v7',copy:'M8 3h13v13H8ZM3 8v13h13',plus:'M12 4v16M4 12h16',x:'m6 6 12 12M6 18 18 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',left:'m14 5-7 7 7 7',right:'m9 5 7 7-7 7',compare:'M5 3v18M19 3v18M5 7h9l-3-3m3 3-3 3M19 17h-9l3-3m-3 3 3 3',folder:'M3 5h7l2 3h9v12H3Z',link:'m9 15 6-6m-6 9-2 2a4 4 0 0 1-6-6l5-5m9-3 2-2a4 4 0 0 1 6 6l-5 5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',check:'m4 12 5 5L20 6',undo:'M3 10h11a6 6 0 1 1 0 12M3 10l5-5m-5 5 5 5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',feather:'m5 20 9-9m-8 8c-2-5 1-14 9-16 3 2 5 4 6 7-2 7-10 10-15 9Z',paw:'M7 16c0-5 10-5 10 0 0 4-10 4-10 0ZM5 8v3m5-7v4m5-4v4m5 0v3',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',more:'M5 12h1m5 0h1m5 0h1'};
const icon=(name)=>`<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${glyphs[name]||glyphs.gem}"/></svg>`;
const btn=(action,label,ico='',extra='')=>`<button type="button" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const chip=(label,kind='')=>`<span class="chip ${kind}">${e(label)}</span>`;
const field=(key,label,options,value)=>`<label class="field"><span>${e(label)}</span><select id="${key}" data-field="${key}">${options.map(([id,name])=>`<option value="${e(id)}" ${value===id?'selected':''}>${e(name)}</option>`).join('')}</select></label>`;
const tabs=[['equipment','Equipment','sword'],['skills','Skills & Stigmas','spark'],['daevanion','Daevanion','map'],['collections','Collections','gem'],['notes','Rotation & Notes','book'],['compare','Compare','compare']];
const safeUrl=s=>typeof s==='string'&&(/^https:\/\//.test(s)||/^\/(?!\/)/.test(s));
function art(item,fallback='gem'){
 if(!item)return `<span class="art placeholder">${icon(fallback)}</span>`;
 if(item.iconPosition&&safeUrl(item.iconSrc)){const [x,y]=item.iconPosition,pet=item.iconSrc.includes('pets');return `<span class="art sprite" style="background-image:url('${e(item.iconSrc).replace(/'/g,'%27')}');background-size:${pet?1600:800}% ${pet?1300:700}%;background-position:${x/(pet?15:7)*100}% ${y/(pet?12:6)*100}%" aria-hidden="true"></span>`;}
 return `<span class="art">${safeUrl(item.icon)?`<img src="${e(item.icon)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:icon(fallback)}</span>`;
}
let catalog,doc=newDoc(),tab='equipment',gearFilter='All',skillFilter='all',search='',selectedSkill='',board='Nezekan',nodeFocus='',compareId='',onlyChanges=true,modal=null;
let history=[],future=[],saveTimer,toastTimer,uiScale='comfortable',autosave='Ready to plan',lastFocus=null,storageBlocked=false,pendingPrevious=null;
const cache={},errors={},requests=new Map();
const v=()=>active(doc),cl=()=>catalog.classes.find(c=>c.slug===v().classSlug);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function readLibrary(){try{const list=JSON.parse(localStorage.getItem(LIBRARY)||'[]');return Array.isArray(list)?list.flatMap(x=>{try{return [normalize(x)];}catch{return [];}}):[];}catch{return [];}}
function archive(d){const list=readLibrary().filter(x=>x.id!==d.id);list.unshift(clone(d));localStorage.setItem(LIBRARY,JSON.stringify(list.slice(0,30)));}
function persist(){
 if(storageBlocked){autosave='Old draft protected · export new work';return updateSaveState();}
 try{if(pendingPrevious){archive(pendingPrevious);pendingPrevious=null;}localStorage.setItem(STORAGE,JSON.stringify(doc));autosave='Saved on this device';}
 catch{autosave='Not saved · export a backup';toast('Storage is unavailable or full. Export a backup to keep your work.');}
 updateSaveState();
}
function updateSaveState(){const el=$('#save-state');if(el)el.textContent=autosave;}
function scheduleSave(){autosave=storageBlocked?'Old draft protected · export new work':'Saving…';updateSaveState();clearTimeout(saveTimer);saveTimer=setTimeout(persist,450);}
function mutate(fn){const next=clone(doc);fn(active(next),next);if(JSON.stringify(next)===JSON.stringify(doc))return;history.push(clone(doc));if(history.length>30)history.shift();future=[];doc=next;doc.updatedAt=Date.now();scheduleSave();render();}
function saveBuild(){try{archive(doc);scheduleSave();toast('Saved in My builds on this device.');}catch{toast('Could not save. Export a JSON backup.');}}
function retain(fn){
 const f=document.activeElement,id=f?.id,identity={...(f?.dataset||{})};let start,end;try{start=f?.selectionStart;end=f?.selectionEnd;}catch{}
 const positions=[...document.querySelectorAll('[data-scroll]')].map(n=>[n.dataset.scroll,n.scrollTop,n.scrollLeft]);
 const opened=[...document.querySelectorAll('details[open][data-key]')].map(n=>n.dataset.key);
 fn();positions.forEach(([key,y,x])=>document.querySelector(`[data-scroll="${key}"]`)?.scrollTo(x,y));
 for(const key of opened){const d=[...document.querySelectorAll('details[data-key]')].find(n=>n.dataset.key===key);if(d)d.open=true;}
 let n=id?document.getElementById(id):null;if(!n&&identity.action)n=[...document.querySelectorAll('[data-action]')].find(n=>Object.keys(identity).every(k=>n.dataset[k]===identity[k]));
 if(n){n.focus({preventScroll:true});try{if(start!=null)n.setSelectionRange(start,end);}catch{}}
}
function resetView(){selectedSkill='';nodeFocus='';search='';}
function openModal(m){lastFocus={id:document.activeElement?.id,data:{...(document.activeElement?.dataset||{})}};modal={...m,token:uid()};drawModal();if(!dialog.open)dialog.showModal();requestAnimationFrame(()=>dialog.querySelector('input:not([readonly]),button,select')?.focus());}
function closeModal(){if(dialog.open)dialog.close();modal=null;let n=lastFocus?.id?document.getElementById(lastFocus.id):null;if(!n&&lastFocus?.data?.action)n=[...document.querySelectorAll('[data-action]')].find(x=>Object.keys(lastFocus.data).every(k=>x.dataset[k]===lastFocus.data[k]));n?.focus({preventScroll:true});}
function heading(title,description='',actions=''){return `<div class="section-head"><div><h2>${e(title)}</h2>${description?`<p>${e(description)}</p>`:''}</div>${actions}</div>`;}
function render(){if(!catalog)return;retain(()=>{
 const a=v(),totals=summary(a,catalog),statGroups=groupSummaryRows(totals.rows),checks=buildChecks(a,catalog,cache),slots=slotsFor(a,catalog),count=slots.filter(s=>selectedItem(a,s,catalog)).length,configured=slots.filter(s=>{const g=a.gear[s.id];return g&&[g.enchant,g.potential,g.substats,g.philosopherStone,g.magicstones,g.note].some(Boolean);}).length;
 root.innerHTML=`<div class="shell ${uiScale==='large'?'large':''}" data-view="${tab}">
 <header class="topbar"><a class="brand" href="/?menu=open" aria-label="Return to DAEVEXUS"><span class="crest">✦</span><span>DAEVEXUS<small>BUILD CREATOR <b>LAB</b></small></span></a><label class="build-title"><span class="eyebrow">BUILD NAME</span><input id="build-title" data-field="title" value="${e(doc.title)}" maxlength="120" aria-label="Build name"></label><span class="save-state" id="save-state" role="status">${e(autosave)}</span><div class="top-actions">${btn('library','My builds','folder')}${btn('save','Save','save')}${btn('share','Share','link','class="gold"')}${btn('menu','More','more')}</div></header>
 <div class="contextbar"><label class="context-field variant-field"><span>VARIANT</span><select id="variant-select" data-variant aria-label="Current variant">${doc.variants.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></label>${btn('duplicate','','copy',`class="icon-button" title="Duplicate variant" aria-label="Duplicate variant" ${doc.variants.length>=10?'disabled':''}`)}${btn('variant-settings','','settings','class="icon-button" title="Variant options" aria-label="Variant options"')}${field('classSlug','CLASS',catalog.classes.map(c=>[c.slug,c.name]),a.classSlug)}${field('region','REGION',[['GLOBAL','Global reference'],['KR_TW','Korea / Taiwan']],a.region)}${btn('character',`${e(a.faction)} · Lv. ${a.level} · ${e(a.goal)}`,'settings','class="character-button" aria-label="Character settings"')}<div class="history-actions">${btn('undo','','undo',`class="icon-button" aria-label="Undo" title="Undo" ${history.length?'':'disabled'}`)}${btn('redo','','right',`class="icon-button" aria-label="Redo" title="Redo" ${future.length?'':'disabled'}`)}</div></div>
 <div class="workarea"><section class="editor"><div class="tabs" role="tablist" aria-label="Build sections">${tabs.map(([id,label,i])=>`<button id="tab-${id}" role="tab" aria-selected="${tab===id}" aria-controls="editor-panel" tabindex="${tab===id?0:-1}" data-action="tab" data-id="${id}" class="${tab===id?'selected':''}">${icon(i)}<span>${label}</span></button>`).join('')}</div><div id="editor-panel" class="editor-body ${tab==='skills'?'skills-editor':tab==='daevanion'?'board-editor':''}" data-scroll="editor" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='equipment'?equipmentView():tab==='skills'?skillsView():tab==='daevanion'?boardView():tab==='collections'?collectionsView():tab==='notes'?notesView():compareView()}</div></section>
 <aside class="summary" aria-label="Loadout stats"><div class="summary-head"><div class="summary-heading"><div><span class="eyebrow">LOADOUT STATS</span><h2>Recorded bonuses</h2></div>${btn('sources','','eye','class="icon-button" aria-label="Data and calculation scope" title="Calculation scope"')}</div><div class="summary-counts"><span><b>${count}/${slots.length}</b> gear</span><span><b>${configured}</b> tuned</span><span><b>${totals.rows.length}</b> stats</span></div><p class="subtle">${a.region==='GLOBAL'?'Global':'KR/TW'} reference · fixed recorded values only</p></div><div class="summary-body" data-scroll="summary">${totals.rows.length?`<p class="summary-hint">Stats are grouped for faster scanning. Open any value to see exactly which items contribute.</p>${statGroups.map(group=>`<section class="stat-group" data-group="${e(group.name)}"><div class="stat-group-head"><h3>${e(group.name)}</h3><span>${group.rows.length}</span></div>${group.rows.map(r=>`<details class="stat-detail" data-key="stat-${e(r.key)}"><summary><span>${e(r.label)}</span><strong>${format(r.value)}${r.unit}</strong></summary><div>${r.sources.map(s=>`<p><span>${e(s.name)}</span><b>${format(s.value)}${r.unit}</b></p>`).join('')}${r.unit?'<p>Reference percentage sum; not a final combat multiplier.</p>':''}</div></details>`).join('')}</section>`).join('')}`:`<div class="empty-summary">${icon('shield')}<h3>${count?'No fixed bonuses recorded':'Start with your equipment'}</h3><p>${count?'Your selections are saved. This reference has no calculable values for them.':'Choose a slot to inspect and equip an item. Your loadout stats will appear here.'}</p>${btn('quick-start','Choose main weapon','plus','class="gold"')}</div>`}</div><div class="summary-foot">${btn('checks',`${checks.length?checks.length+' planning checks':'Review selections'}${totals.excluded.length?' · '+totals.excluded.length+' calculation notes':''}`,'eye','class="wide"')}<small>Enhancement, potential, substats and stones stay excluded until their formulas are verified.</small></div></aside></div>
 <footer><span>Independent prototype · local saves</span><div>${btn('size',uiScale==='large'?'Comfortable text':'Larger text','eye','class="quiet"')}${btn('export','Export','download','class="quiet"')}${btn('import','Import','folder','class="quiet"')}</div></footer></div>`;
 });}
function equipmentView(){const a=v(),slots=slotsFor(a,catalog),shown=slots.filter(s=>gearFilter==='All'||s.family===gearFilter);return heading('Equipment','All slots together. Select a slot to compare items before equipping.',`<span class="subtle">${slots.filter(s=>selectedItem(a,s,catalog)).length} / ${slots.length} equipped</span>`)+`<div class="segmented equipment-filters" role="group" aria-label="Equipment groups">${['All','Weapons','Armor','Accessories'].map(f=>btn('gear-filter',f,'',`data-id="${f}" class="${gearFilter===f?'selected':''}" aria-pressed="${gearFilter===f}"`)).join('')}</div><div class="gear-grid">${shown.map(s=>{const item=selectedItem(a,s,catalog),g=a.gear[s.id],needsLevel=item&&Number(item.requiredLevel)>a.level,planCount=g?[g.potential,g.substats,g.philosopherStone,g.magicstones,g.note].filter(Boolean).length:0;return `<article class="gear-card ${item?'filled':''}"><button class="gear-main" data-action="pick" data-kind="equipment" data-slot="${s.id}" aria-label="${e((item?'Change ':'Choose ')+s.label)}">${art(item,s.family==='Weapons'?'sword':s.family==='Armor'?'shield':'gem')}<span><small>${s.label}</small><strong>${e(item?.name||(g?'Saved item unavailable':'Empty slot'))}</strong><em>${needsLevel?'Requires Lv. '+e(item.requiredLevel):item?e(item.grade)+(g.enchant?' · target +'+g.enchant:'')+(planCount?' · '+planCount+' plan '+(planCount===1?'field':'fields'):''):s.family==='Weapons'?e((s.id==='offHand'?cl()?.offTypes:cl()?.mainTypes)?.join(' / ')||'No reference'):'Select an item'}</em></span>${icon(item?'right':'plus')}</button>${item?`<div class="gear-actions">${btn('configure','','settings','data-slot="'+s.id+'" title="Configure '+s.label+'" aria-label="Configure '+s.label+'"')}${btn('remove-gear','','x','data-slot="'+s.id+'" title="Remove '+s.label+'" aria-label="Remove '+s.label+'"')}</div>`:''}</article>`;}).join('')}</div>`;}
function skillsView(){const a=v(),list=(cl()?.skills||[]).filter(s=>(skillFilter==='all'||s.type===skillFilter)&&s.name.toLowerCase().includes(search.toLowerCase()));return heading('Skills & Stigmas','Inspect a skill, set its level and choose specializations.')+`<div class="section-tools"><label class="search">${icon('search')}<input id="skill-search" data-search="skills" value="${e(search)}" placeholder="Search skills…" aria-label="Search skills"></label><div class="segmented" role="group" aria-label="Skill type">${['all','active','passive','stigma'].map(t=>btn('skill-filter',t==='all'?'All':t[0].toUpperCase()+t.slice(1),'',`data-id="${t}" class="${t===skillFilter?'selected':''}" aria-pressed="${t===skillFilter}"`)).join('')}</div></div><div class="skill-workspace"><div class="skill-grid" data-scroll="skills">${list.map(s=>`<button class="skill-card ${selectedSkill===s.id?'inspecting':''} ${a.skills[s.id]?'selected':''}" data-action="skill" data-id="${s.id}" aria-label="Inspect ${e(s.name)}">${art(s,'spark')}<span><strong>${e(s.name)}</strong><small>${e(s.type)}${a.skills[s.id]?' · Lv. '+a.skills[s.id].level:''}</small></span>${icon(a.skills[s.id]?'check':'right')}</button>`).join('')||'<p class="empty">No skills match this search.</p>'}</div><section class="skill-inspector" data-scroll="skill-detail" aria-label="Selected skill">${selectedSkill?skillDetail(selectedSkill):`<div class="empty"><span class="crest">✦</span><h3>Inspect a skill</h3><p>Choose from the list to see its recorded effects, levels and related skills here.</p></div>`}</section></div>`;}
function skillDetail(id){const skill=cl()?.skills.find(s=>s.id===id);if(!skill)return '<p>This skill is not in the current class catalog.</p>';const info=cache[id],saved=v().skills[id],levels=skillLevels(info),level=saved?.level||levels[0]||1,view=detailForSkill(info,level),tiers=new Map();(info?.specialties||[]).forEach(s=>tiers.set(Number(s.level),[...(tiers.get(Number(s.level))||[]),s.description]));
 return `<div class="skill-detail-head">${art(skill,'spark')}<div><span class="eyebrow">${e(skill.type)}</span><h3>${e(skill.name)}</h3><small>${saved?'Included · Lv. '+saved.level:'Not selected'}</small>${info?`<div class="skill-badges">${[info.requiredLevel?'Required Lv. '+info.requiredLevel:'',info.mastery,info.category].filter(Boolean).map(x=>chip(x)).join('')}</div>`:''}</div></div>${btn(saved?'unselect-skill':'select-skill',saved?'Remove from build':'Add to build',saved?'x':'plus',`class="${saved?'':'gold'} wide" data-id="${id}"`)}${!info?`<div class="empty">${errors[id]?`<p>Reference details are unavailable. You can still save the selection.</p>${btn('retry-skill','Retry details','','data-id="'+id+'"')}`:'Loading reference details…'}</div>`:`<p class="skill-description">${e(view.description||'No description recorded.').replace(/\n/g,'<br>')}</p>${saved&&levels.length?`<div class="level-editor"><div><b>Skill level</b><strong>Lv. ${level} / ${levels.at(-1)}</strong></div>${!levels.includes(level)?'<p class="warning-text">Saved level is not in this reference. Select a recorded level below.</p>':''}<div class="level-buttons">${btn('skill-min','Min','','data-id="'+id+'"')}${btn('skill-step','−','',`data-id="${id}" data-dir="-1" aria-label="Decrease skill level" ${level===levels[0]?'disabled':''}`)}<input id="skill-level" data-skill-range="${id}" type="range" min="0" max="${levels.length-1}" value="${Math.max(0,levels.indexOf(level))}" aria-label="Skill level">${btn('skill-step','+','',`data-id="${id}" data-dir="1" aria-label="Increase skill level" ${level===levels.at(-1)?'disabled':''}`)}${btn('skill-max','Max','','data-id="'+id+'"')}</div></div>`:saved?'<p class="subtle">No recorded level range; a maximum is not guessed.</p>':''}
 ${statRows(view.rows)}${info.properties?`<p class="properties">${e(info.properties)}</p>`:''}${[...tiers].sort((x,y)=>x[0]-y[0]).map(([unlock,options])=>`<fieldset class="specialties" ${!saved||level<unlock?'disabled':''}><legend>Lv. ${unlock} · ${!saved||level<unlock?'Locked':'Specialization'}</legend>${skill.type==='stigma'||options.length===1?`<p>${e(options.join(' · '))}</p><small>${saved&&level>=unlock?'Automatic effect in reference':'Unlocks at this level'} · not added to totals</small>`:options.map((o,i)=>btn('specialty',e(o),'',`data-id="${id}" data-unlock="${unlock}" data-index="${i}" class="${saved?.spec?.[unlock]===i?'selected':''}" aria-pressed="${saved?.spec?.[unlock]===i}"`)).join('')}</fieldset>`).join('')}
 ${view.details.length?`<h4>Recorded details</h4>${statRows(view.details)}`:''}${view.chain.filter(x=>x.id!==id&&x.name!==skill.name).length?`<h4>Related skills</h4><div class="related-list">${view.chain.filter(x=>x.id!==id&&x.name!==skill.name).map(x=>`<div>${art({icon:/^\d{6,12}$/.test(String(x.id))?'https://aion2hub.com/api/skill-icon/'+x.id:''},'spark')}<span><strong>${e(x.name)}</strong>${x.step?`<small>${e(x.step)}</small>`:''}</span></div>`).join('')}</div>`:''}<p class="subtle">Reference effects only. Not a damage simulation.</p>`}`;
}
function statRows(rows,empty='No fixed numeric record available.'){return `<div class="preview-stats">${rows.length?rows.map(r=>`<div><span>${e(r.label)}</span><b>${e(r.value)}</b></div>`).join(''):`<p>${e(empty)}</p>`}</div>`;}
function collectionStats(item,kind,level){const rows=collectionRows(item,kind,level);return `<div class="collection-stats">${rows.length?rows.map(r=>`<div><span>${e(r.label)}</span><b>${recordStatus(r)==='unknown'?'Unverified':e(r.value)}</b></div>`).join(''):'<p>No numeric values recorded.</p>'}</div>`;}
function collectionsView(){const a=v(),wing=catalog.wings.find(x=>x.id===a.wingId),pet=catalog.pets.find(x=>x.id===a.petId);return heading('Collections','Selections, recorded bonuses and pet levels in one place.')+`<div class="collection-layout"><div class="companions">${[['wings','Wings',wing],['pets','Companion',pet]].map(([kind,label,item])=>`<article class="collection-card"><div class="collection-title">${art(item,kind==='wings'?'feather':'paw')}<div><span class="eyebrow">${label}</span><h3>${e(item?.name||'No selection')}</h3><small>${e(item?item.grade||item.genus||'Reference':'Choose from the catalog')}</small></div></div>${item?`${kind==='pets'?`<label class="pet-level">Recorded level <select data-field="petLevel" id="pet-level">${(petLevels(item).length?petLevels(item):[a.petLevel]).map(n=>`<option value="${n}" ${n===a.petLevel?'selected':''}>${n}</option>`).join('')}</select></label>`:''}${collectionStats(item,kind,a.petLevel)}<p class="subtle">${item.region===a.region?'Fixed recorded bonuses included.':'KR/TW reference · excluded from Global totals.'}</p>`:''}<div class="collection-actions">${btn('pick',item?'Change':'Choose '+(kind==='pets'?'pet':'wings'),'plus',`data-kind="${kind}"`)}${item?btn('remove-collection','Remove','','class="quiet" data-kind="'+kind+'"'):''}</div></article>`).join('')}</div><section class="arcana-section"><h3>Arcana <small>${a.arcana.filter(Boolean).length}/10 planned slots</small></h3><div class="arcana-grid">${a.arcana.map((id,i)=>{const item=catalog.arcana.find(x=>x.id===id);return `<article class="arcana-card">${btn('pick',`${art(item)}<span><small>Slot ${i+1}</small><strong>${e(item?.name||'Add Arcana')}</strong></span>`,'',`data-kind="arcana" data-slot="${i}"`)}${item?`<div class="arcana-info">${collectionStats(item,'arcana')}<div>${btn('remove-arcana','Remove','','class="quiet" data-slot="'+i+'"')}</div></div>`:''}</article>`;}).join('')}</div><p class="subtle">Planning slots are not a verified Global cap. Unsupported values are excluded.</p></section></div>`;}
function boardView(){const a=v(),className=cl()?.name,key=className==='Spiritmaster'?'Elementalist':className,names=Object.keys(catalog.boards[key]||catalog.boards[className]||{});if(!names.includes(board))board=names[0]||'';const nodes=boardNodes(a,catalog,board);if(!nodes.length)return heading('Daevanion')+'<p class="empty">No board topology for this class in the current reference.</p>';const path=a.paths[board]||[],chosen=nodes.filter(n=>path.includes(n.id)),cost=chosen.reduce((n,x)=>n+x.cost,0),r0=Math.min(...nodes.map(n=>n.r)),c0=Math.min(...nodes.map(n=>n.col)),rows=Math.max(...nodes.map(n=>n.r))-r0+1,columns=Math.max(...nodes.map(n=>n.col))-c0+1,focus=nodes.find(n=>n.id===nodeFocus),budget=a.budgets[board]||0;
 return heading('Daevanion','Select a destination to connect the lowest-cost reference path.')+`<div class="section-tools board-tools"><label class="field"><span>BOARD</span><select id="board-select" data-board>${names.map(n=>`<option ${n===board?'selected':''}>${e(n)}</option>`).join('')}</select></label><label class="field"><span>PLANNING BUDGET · 0 = UNLIMITED</span><input id="board-budget" data-budget type="number" min="0" max="9999" step="1" value="${budget}"></label><span class="board-cost">${cost}${budget?' / '+budget:''} cost · ${chosen.length} nodes</span>${btn('clear-board','Clear','','class="quiet"')}</div>${budget&&cost>budget?'<p class="warning-text">Current path exceeds your budget; remove nodes or increase it.</p>':''}<div class="board-layout"><div class="board-scroll" data-scroll="board"><div class="node-grid" style="--columns:${columns};--rows:${rows}">${nodes.map(n=>`<button data-action="node" data-id="${n.id}" class="node ${n.start?'start':''} ${path.includes(n.id)?'lit':''}" style="grid-column:${n.col-c0+1};grid-row:${n.r-r0+1}" title="${e(n.label)} · reference cost ${n.cost}" aria-label="${e(n.label)}, reference cost ${n.cost}" aria-pressed="${path.includes(n.id)||n.start}">${icon(n.start?'spark':n.label.includes('Skill')?'book':n.label.includes('Attack')?'sword':'gem')}</button>`).join('')}</div></div><div class="board-ledger" data-scroll="ledger"><h3>${e(focus?.label||board)}</h3><p>${focus?'Reference cost: '+focus.cost:'Hover or focus a node to see its effect.'}</p><h4>Selected path</h4>${chosen.map(n=>`<div><span>${e(n.label)}</span><b>${n.cost}</b></div>`).join('')||'<p>No nodes chosen.</p>'}<p class="subtle">Costs are not stat amounts. Node bonuses remain uncalculated.</p></div></div>`;
}
function notesView(){const a=v(),selected=(cl()?.skills||[]).filter(s=>a.skills[s.id]&&s.type!=='passive');return heading('Rotation & Notes','Arrange your opening sequence and explain the build.')+`<div class="notes-layout"><section class="rotation"><h3>Opening sequence <small>${a.rotation.length}/24</small></h3><div class="rotation-list">${a.rotation.map((id,i)=>{const skill=cl()?.skills.find(s=>s.id===id);return `<article><span class="step-number">${i+1}</span>${art(skill,'spark')}<strong>${e(skill?.name||id)}</strong><div>${btn('rotation-left','↑','',`data-index="${i}" aria-label="Move step up" ${i===0?'disabled':''}`)}${btn('rotation-right','↓','',`data-index="${i}" aria-label="Move step down" ${i===a.rotation.length-1?'disabled':''}`)}${btn('rotation-remove','×','',`data-index="${i}" aria-label="Remove step"`)}</div></article>`;}).join('')||'<p class="empty">Select active skills or Stigmas, then add them below.</p>'}</div><div class="rotation-options">${selected.map(s=>btn('rotation-add',e(s.name),'plus','data-id="'+s.id+'"')).join('')}</div></section><label class="notes-label"><h3>Build guide</h3><textarea id="notes" data-field="notes" maxlength="12000" placeholder="Priorities, timing, alternatives, acquisition goals and why you chose this variant…">${e(a.notes)}</textarea><span class="subtle">Saved locally. Notes are included in shared links.</span></label></div>`;}
function compareView(){const a=v(),choices=doc.variants.filter(x=>x.id!==a.id),b=choices.find(x=>x.id===compareId)||choices[0];if(!b)return heading('Compare variants')+`<div class="empty"><span class="crest">⇄</span><h3>Try a change without losing your setup</h3><p>Duplicate this variant, change an item and compare the results.</p>${btn('duplicate','Duplicate variant','copy','class="gold"')}</div>`;compareId=b.id;const same=a.region===b.region,rows=differences(summary(a,catalog),summary(b,catalog)).filter(r=>!onlyChanges||r.delta!==0),changes=compareSystems(a,b,catalog);
 return heading('Compare variants','B minus A. A difference is not a judgment of which build is better.')+`<div class="compare-pair"><div><span class="eyebrow">A · CURRENT</span><h3>${e(a.name)}</h3><small>${e(a.classSlug+' · '+a.region)}</small></div><label class="field"><span>B · COMPARE WITH</span><select id="compare-select" data-compare>${choices.map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${e(x.name)}</option>`).join('')}</select><small>${e(b.classSlug+' · '+b.region)}</small></label>${btn('compare-filter',onlyChanges?'Show all bonuses':'Changes only','','class="quiet"')}</div>${!same?'<p class="inline-note">Different regions: numeric deltas are not comparable and are withheld.</p>':''}<div class="compare-layout"><section><h3>Recorded bonus changes</h3><div class="table-scroll"><table class="compare-table"><thead><tr><th>Bonus</th><th>A</th><th>B</th><th>Δ</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(r.label)}</td><td>${format(r.a)}${r.unit}</td><td>${format(r.b)}${r.unit}</td><td class="delta">${same?(r.delta>0?'+':'')+format(r.delta)+(r.unit?' pp':''):'—'}</td></tr>`).join('')||'<tr><td colspan="4">No differences in recorded numeric bonuses.</td></tr>'}</tbody></table></div></section><section class="comparison-changes"><h3>Configuration changes <small>${changes.length}</small></h3>${changes.map(r=>`<article><span class="eyebrow">${e(r.system)}</span><h4>${e(r.label)}</h4><div><small>A</small><span>${e(r.a)}</span></div><div><small>B</small><span>${e(r.b)}</span></div></article>`).join('')||'<p class="empty">These variants have the same configuration.</p>'}</section></div>`;
}

function pickerItems(){
 const a=v(),slot=SLOTS.find(s=>s.id===modal.slot);
 const options=modal.kind==='equipment'?catalog.equipment.filter(i=>slot&&compatible(i,slot,a,catalog)):modal.kind==='wings'?catalog.wings.filter(i=>i.faction===a.faction):modal.kind==='pets'?catalog.pets:catalog.arcana.filter(i=>i.region===a.region);
 return options.filter(i=>(!modal.q||(i.name+' '+(i.category||'')+' '+(i.genus||'')).toLowerCase().includes(modal.q.toLowerCase()))&&(!modal.grade||i.grade===modal.grade));
}
function itemPreview(item){
 const a=v(),isGear=modal.kind==='equipment',recordLevel=modal.petLevel||petLevels(item)[0]||1;let deltas=[];
 if(isGear){const next=clone(a);next.gear[modal.slot]={id:item.id,enchant:0,potential:'',substats:'',philosopherStone:'',magicstones:'',note:''};deltas=differences(summary(a,catalog),summary(next,catalog)).filter(r=>r.delta);}
 const rows=collectionRows(item,modal.kind,recordLevel),requisites=[['Item level',item.itemLevel],['Required level',item.requiredLevel],['Type',item.category||item.genus],['Class restriction',item.classRestrictions],['Faction',item.faction]].filter(([,value])=>value).map(([label,value])=>({label,value}));
 return `<div class="preview-title">${art(item)}<div>${chip(item.grade||item.genus||'Reference')}<h3>${e(item.name)}</h3><small>${e(item.region||'KR/TW')} · community reference</small></div></div><div class="preview-callout">${btn('equip-preview',isGear?'Use this item':'Use in this variant','check',`class="gold wide" data-id="${e(item.id)}"`)}${Number(item.requiredLevel)>a.level?`<p class="warning-text">Requires reference Lv. ${e(item.requiredLevel)}; your planned level is ${a.level}.</p>`:''}</div>${modal.kind==='pets'&&petLevels(item).length?`<label class="pet-level">Preview pet level <select id="preview-pet-level" data-preview-level>${petLevels(item).map(n=>`<option ${n===recordLevel?'selected':''}>${n}</option>`).join('')}</select></label>`:''}<h4>Recorded stats</h4><div class="preview-stats">${rows.map(r=>`<div><span>${e(r.label)}</span><b>${recordStatus(r)==='unknown'?'Unverified value':e(r.value)}</b></div>`).join('')||'<p>No numeric values in this record.</p>'}</div>${isGear?`<h4>Change to your recorded bonuses</h4><div class="preview-stats">${deltas.map(r=>`<div><span>${e(r.label)}</span><b class="delta">${r.delta>0?'+':''}${format(r.delta)}${r.unit?' pp':''}</b></div>`).join('')||'<p>No change in fixed numeric bonuses.</p>'}</div>`:''}${requisites.length?`<h4>Requirements & type</h4>${statRows(requisites)}`:''}${item.details?.length?`<details class="reference-more"><summary>More recorded details</summary>${statRows(pairs(item.details))}</details>`:''}${item.upgrades?`<details class="reference-more"><summary>Upgrade reference</summary><p>${e(item.upgrades)}</p></details>`:''}${item.obtain?.length?`<details class="reference-more"><summary>Acquisition reference</summary><p>${e(Array.isArray(item.obtain)?item.obtain.join(' · '):item.obtain)}</p></details>`:''}<p class="subtle">${isGear?'Fixed base values only. Enhancement and imprint targets are not simulated.':item.region===a.region?'Same-region fixed values can contribute to totals.':'Different-region bonuses are excluded from your current totals.'}</p>`;
}
function drawModal(){if(!modal||!catalog)return;retain(()=>{
 const a=v();let title='',content='',kind=modal.type;
 if(kind==='picker'){
  const items=pickerItems(),item=items.find(i=>i.id===modal.preview),all=modal.kind==='equipment'?catalog.equipment:modal.kind==='wings'?catalog.wings:modal.kind==='pets'?catalog.pets:catalog.arcana;
  title=modal.kind==='equipment'?'Choose '+(SLOTS.find(s=>s.id===modal.slot)?.label||'item'):modal.kind==='arcana'?'Arcana · slot '+(Number(modal.slot)+1):'Choose '+modal.kind;
  content=`<div class="picker-tools"><label class="search">${icon('search')}<input id="picker-search" data-search="picker" value="${e(modal.q||'')}" placeholder="Search by name…" aria-label="Search items"></label><select id="picker-grade" data-grade aria-label="Filter rarity"><option value="">All rarities</option>${[...new Set(all.map(i=>i.grade).filter(Boolean))].map(g=>`<option value="${e(g)}" ${g===modal.grade?'selected':''}>${e(g)}</option>`).join('')}</select><span class="subtle">${items.length} results</span></div><div class="picker-grid"><div class="picker-list" data-scroll="picker">${items.slice(0,modal.limit||60).map(i=>`<button data-action="preview-item" data-id="${e(i.id)}" class="pick-row ${i.id===modal.preview?'selected':''}" aria-pressed="${i.id===modal.preview}">${art(i)}<span><strong>${e(i.name)}</strong><small>${e(i.grade||i.genus||'Reference')}${i.itemLevel?' · Item Lv. '+e(i.itemLevel):''}</small></span>${icon('right')}</button>`).join('')||'<p class="empty">No compatible entries match these filters.</p>'}${items.length>(modal.limit||60)?btn('more-results','Show more','','class="wide"'):''}</div><section class="item-preview" data-scroll="preview">${item?itemPreview(item):`<div class="empty">${icon('eye')}<h3>Inspect before equipping</h3><p>Select an entry to see its requirements, recorded values and changes to your build.</p></div>`}</section></div>`;
 }else if(kind==='configure'){
  const item=selectedItem(a,SLOTS.find(s=>s.id===modal.slot),catalog),g=a.gear[modal.slot];title='Configure '+(item?.name||'item');
  content=item?`<p class="inline-note">Equipment tuning is saved as planning data. Only recorded base stats contribute to the summary; unverified rolls, stones and enhancement effects are never invented.</p><div class="configure-grid"><section><label class="field"><span>ENHANCEMENT TARGET · PLANNER LIMIT 30</span><input id="enchant" data-enchant type="number" min="0" max="30" step="1" value="${g.enchant||0}"></label><label class="field"><span>POTENTIAL TARGET</span><input id="gear-potential" data-gear-plan="potential" maxlength="120" value="${e(g.potential||'')}" placeholder="Desired potential / tier / roll"></label><label class="notes-label"><span>RANDOM / SUBSTAT TARGETS</span><textarea id="gear-substats" data-gear-plan="substats" maxlength="300" style="min-height:5em" placeholder="Critical Hit, Attack, Accuracy…">${e(g.substats||'')}</textarea></label><label class="field"><span>PHILOSOPHER'S STONE</span><input id="gear-philosopher" data-gear-plan="philosopherStone" maxlength="180" value="${e(g.philosopherStone||'')}" placeholder="Stone / desired effect"></label><label class="notes-label"><span>MAGICSTONES</span><textarea id="gear-magicstones" data-gear-plan="magicstones" maxlength="300" style="min-height:5em" placeholder="Planned stones / sockets…">${e(g.magicstones||'')}</textarea></label><label class="notes-label"><span>ADDITIONAL NOTES</span><textarea id="gear-note" data-gear-note maxlength="600" style="min-height:6em" placeholder="Acquisition, replacement or farming notes…">${e(g.note||'')}</textarea></label></section><section><h3>Recorded base stats</h3>${statRows(pairs(item.stats),'No base stats recorded.')}<h3>Recorded imprint options</h3>${statRows(pairs(item.imprints),'No imprint options recorded.')}<h4>Upgrade reference</h4><p>${e(item.upgrades||'No verified progression formula in this record.')}</p></section></div>`:'<p>This item is no longer available in the current variant.</p>';
 }else if(kind==='character'){
  title='Character settings';content=`<p>These settings apply only to <strong>${e(a.name)}</strong>.</p><div class="form-grid">${field('faction','FACTION',[['Elyos','Elyos'],['Asmodians','Asmodians']],a.faction)}${field('goal','BUILD GOAL',[['PvE','PvE · Group'],['PvP','PvP · Abyss'],['Solo','Solo progression'],['Support','Support / Healer']],a.goal)}<label class="field"><span>PLANNED LEVEL</span><input id="level" data-field="level" type="number" min="1" max="100" step="1" value="${a.level}"></label></div><p class="subtle">Level 100 is a planning input limit, not a verified Global game cap. Item requirements are checked against your planned level.</p><p class="subtle">Changing faction clears only this variant’s wing selection.</p>`;
 }else if(kind==='variant-settings'){
  title='Variant options';content=`<form id="rename-form"><label class="field"><span>VARIANT NAME</span><input id="variant-name" maxlength="80" value="${e(a.name)}" required></label><div class="modal-actions"><button type="submit" class="gold">Save name</button>${btn('delete-variant','Delete this variant','x',doc.variants.length===1?'disabled':'')}</div></form><p class="subtle">${doc.variants.length} / 10 variants. Other variants are never deleted with this one.</p>`;
 }else if(kind==='library'){
  title='My builds';content=`<p>Saved in this browser. Export a backup to keep a copy elsewhere.</p><div class="library-list">${readLibrary().map(d=>`<article><span class="crest">✦</span><div><h3>${e(d.title)}</h3><small>${d.variants.length} variants · ${e(active(d).classSlug)}</small></div>${btn('load-doc','Open','','data-id="'+d.id+'"')}${btn('delete-doc','Delete','','class="quiet" data-id="'+d.id+'"')}</article>`).join('')||'<p class="empty">Press Save to add this build to your library.</p>'}</div><div class="modal-actions">${btn('save','Save current build','save','class="gold"')}${btn('import','Import JSON','folder')}</div>`;
 }else if(kind==='share'){
  title='Share this build';content=`<p>The link includes all variants and notes. Recipients open a separate copy.</p><textarea id="share-link" class="share-link" readonly aria-label="Build share link">${e(modal.url||'Preparing link…')}</textarea><div class="modal-actions">${btn('copy-link','Copy link','copy','class="gold" '+(!modal.url?'disabled':''))}${btn('export','Export JSON','download')}</div><p class="subtle">Anyone with the link can read your notes. Later edits do not change an already-shared link.</p>`;
 }else if(kind==='checks'){
  title='Planning checks';const checks=buildChecks(a,catalog,cache),totals=summary(a,catalog);
  content=`<h3>Selections & requirements</h3>${checks.length?`<ul class="check-list">${checks.map(x=>`<li>${e(x.label)}</li>`).join('')}</ul>`:'<p>No issue detected in the checked reference fields. This does not certify a game-valid build.</p>'}<h3>Not included in numeric totals</h3>${totals.excluded.length?`<ul class="check-list">${totals.excluded.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:'<p>No selected record currently produces an exclusion note.</p>'}<p class="subtle">Game caps, set effects, unchosen imprint rolls, character base stats and DPS remain unverified.</p>`;
 }else if(kind==='menu'){
  title='Workspace';content=`<div class="workspace-actions">${btn('new','New build','plus')}${btn('export','Export JSON backup','download')}${btn('import','Import JSON','folder')}${btn('sources','Data & calculation scope','eye')}${btn('size',uiScale==='large'?'Use comfortable text':'Use larger text','eye')}</div><p class="subtle">New or imported builds keep the current workspace in My builds before switching, when browser storage is available.</p>`;
 }else if(kind==='sources'){
  title='Data & calculation scope';content=`<div class="scope"><h3>Community reference, not official validation</h3><p>${e(catalog.source)}</p><p>Catalog: ${e(catalog.version)}. UI review: 2.0.</p><h3>Included in the summary</h3><p>Fixed numeric equipment stats and same-region recorded wing, pet-level and Arcana values. Open a bonus row for its contributors. Percentages are additive reference sums, not final combat multipliers.</p><h3>Not calculated</h3><p>Character base stats, enhancement targets, unchosen imprint rolls, ranges, skill/passive effects, set effects, Daevanion stat amounts and DPS. Costs on a board are never treated as stat bonuses.</p><h3>Regional safeguards</h3><p>Equipment and Arcana respect the selected region. KR/TW wings and pets may be planned in Global, but their values are excluded. Numeric deltas across regions are withheld.</p><h3>Storage & limits</h3><p>Local autosave and My builds use only this prototype’s storage keys. There is no account, cloud backup or game-client import. Ten variants, ten Arcana planning slots, a level input of 100 and enhancement target 30 are planner limits, not confirmed game caps. Export backups regularly.</p></div>`;
 }
 dialog.dataset.kind=kind;dialog.innerHTML=`<div class="modal-head"><h2>${e(title)}</h2>${btn('close','','x','class="icon-button" aria-label="Close dialog"')}</div><div class="modal-body" data-scroll="modal">${content}</div>`;
 });}
async function loadSkill(id){
 if(cache[id]||requests.has(id))return;
 delete errors[id];const request=fetch('/api/skill-description/'+encodeURIComponent(id),{signal:AbortSignal.timeout(18000)});requests.set(id,request);
 try{const response=await request;if(!response.ok)throw new Error();const info=await response.json();if(!info||typeof info!=='object')throw new Error();cache[id]=info;}
 catch{errors[id]=true;}finally{requests.delete(id);if(tab==='skills'&&selectedSkill===id)render();}
}
function setSkillLevel(id,level){const levels=skillLevels(cache[id]);if(!v().skills[id]||!levels.includes(level))return;mutate(a=>{a.skills[id].level=level;for(const k of Object.keys(a.skills[id].spec))if(Number(k)>level)delete a.skills[id].spec[k];});}
function exportDoc(){const blob=new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(doc.title.replace(/[^a-z0-9_-]/gi,'-').slice(0,70)||'daevexus-build')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('JSON backup exported.');}
function switchDocument(next,message){
 try{if(pendingPrevious)archive(pendingPrevious);archive(doc);}catch{toast('Could not preserve the current workspace. Export it before switching.');return false;}
 clearTimeout(saveTimer);doc=next;history=[];future=[];pendingPrevious=null;resetView();closeModal();scheduleSave();render();toast(message);return true;
}
async function doAction(el){const action=el.dataset.action,id=el.dataset.id,slot=el.dataset.slot;try{switch(action){
 case 'tab':tab=id;search='';render();$('#editor-panel')?.scrollTo(0,0);break;
 case 'duplicate':if(doc.variants.length>=10)break;mutate((a,d)=>{const b=clone(a);b.id=uid();b.name=(a.name+' · copy').slice(0,80);d.variants.push(b);d.activeId=b.id;});toast('Variant duplicated. The original is unchanged.');break;
 case 'variant-settings':case 'character':case 'library':case 'sources':case 'checks':case 'menu':openModal({type:action});break;
 case 'delete-variant':if(doc.variants.length>1&&confirm('Delete only this variant?')){mutate((a,d)=>{d.variants=d.variants.filter(x=>x.id!==a.id);d.activeId=d.variants[0].id;});resetView();closeModal();render();}break;
 case 'undo':if(history.length){future.push(clone(doc));doc=history.pop();scheduleSave();render();}break;
 case 'redo':if(future.length){history.push(clone(doc));doc=future.pop();scheduleSave();render();}break;
 case 'quick-start':case 'pick':openModal({type:'picker',kind:action==='quick-start'?'equipment':el.dataset.kind,slot:action==='quick-start'?'mainHand':slot,q:'',grade:''});break;
 case 'gear-filter':gearFilter=id;render();break;
 case 'preview-item':modal.preview=id;modal.petLevel=undefined;drawModal();dialog.querySelector('.item-preview')?.scrollTo(0,0);break;
 case 'more-results':modal.limit=(modal.limit||60)+60;drawModal();break;
 case 'equip-preview':{const m={...modal},item=pickerItems().find(x=>x.id===id);if(!item)throw new Error('This entry no longer matches the active filters. Select it again.');mutate(a=>{if(m.kind==='equipment'){const old=a.gear[m.slot];a.gear[m.slot]=old?.id===id?old:{id,enchant:0,potential:'',substats:'',philosopherStone:'',magicstones:'',note:''};}else if(m.kind==='wings')a.wingId=id;else if(m.kind==='pets'){a.petId=id;a.petLevel=m.petLevel||petLevels(item)[0]||1;}else a.arcana[Number(m.slot)]=id;});closeModal();toast('Added to '+v().name+'.');break;}
 case 'remove-gear':mutate(a=>delete a.gear[slot]);break;
 case 'configure':openModal({type:'configure',slot});break;
 case 'skill-filter':skillFilter=id;render();break;
 case 'skill':selectedSkill=id;render();loadSkill(id);if(innerWidth<1000)document.querySelector('.skill-inspector')?.scrollIntoView({block:'start',behavior:'smooth'});break;
 case 'select-skill':if(cl()?.skills.some(s=>s.id===id))mutate(a=>a.skills[id]={level:skillLevels(cache[id])[0]||1,spec:{}});break;
 case 'unselect-skill':mutate(a=>{delete a.skills[id];a.rotation=a.rotation.filter(x=>x!==id);});break;
 case 'retry-skill':loadSkill(id);render();break;
 case 'skill-min':case 'skill-max':case 'skill-step':{const levels=skillLevels(cache[id]);if(!levels.length||!v().skills[id])break;let at=levels.indexOf(v().skills[id].level);at=action==='skill-min'?0:action==='skill-max'?levels.length-1:boundedInt(at+Number(el.dataset.dir),0,levels.length-1);setSkillLevel(id,levels[at]);break;}
 case 'specialty':{const unlock=Number(el.dataset.unlock),index=Number(el.dataset.index),choices=(cache[id]?.specialties||[]).filter(x=>Number(x.level)===unlock);if(v().skills[id]?.level>=unlock&&choices[index])mutate(a=>a.skills[id].spec[unlock]=index);break;}
 case 'remove-collection':mutate(a=>a[el.dataset.kind==='wings'?'wingId':'petId']='');break;
 case 'remove-arcana':mutate(a=>a.arcana[Number(slot)]='');break;
 case 'node':{nodeFocus=id;const path=toggleNode(boardNodes(v(),catalog,board),v().paths[board]||[],id,v().budgets[board]||0);mutate(a=>a.paths[board]=path);break;}
 case 'clear-board':if(confirm('Clear this board in the current variant?'))mutate(a=>a.paths[board]=[]);break;
 case 'rotation-add':if(v().rotation.length>=24)throw new Error('This planner supports 24 rotation steps.');if(v().skills[id])mutate(a=>a.rotation.push(id));break;
 case 'rotation-remove':mutate(a=>a.rotation.splice(Number(el.dataset.index),1));break;
 case 'rotation-left':case 'rotation-right':{const i=Number(el.dataset.index),j=i+(action==='rotation-left'?-1:1);if(j>=0&&j<v().rotation.length)mutate(a=>[a.rotation[i],a.rotation[j]]=[a.rotation[j],a.rotation[i]]);break;}
 case 'compare-filter':onlyChanges=!onlyChanges;render();break;
 case 'save':saveBuild();if(modal?.type==='library')drawModal();break;
 case 'load-doc':{const d=readLibrary().find(x=>x.id===id);if(d&&confirm('Open this build? Your current workspace will be kept in My builds.'))switchDocument(d,'Saved build opened.');break;}
 case 'delete-doc':if(confirm('Delete this saved library entry?')){localStorage.setItem(LIBRARY,JSON.stringify(readLibrary().filter(x=>x.id!==id)));drawModal();}break;
 case 'share':{openModal({type:'share'});const token=modal.token,code=await shareCode(doc);if(modal?.token!==token)break;if(code.length>32000){closeModal();toast('Use a JSON export for this large build.');exportDoc();break;}modal.url=location.origin+'/build-lab#build='+code;drawModal();break;}
 case 'copy-link':try{await navigator.clipboard.writeText(modal.url);toast('Link copied.');}catch{$('#share-link').focus();$('#share-link').select();toast('Copy the highlighted link.');}break;
 case 'export':exportDoc();break;
 case 'import':$('#import-file').click();break;
 case 'new':if(confirm('Start a new build? The current workspace will be kept in My builds.'))switchDocument(newDoc(),'New build started.');break;
 case 'size':uiScale=uiScale==='large'?'comfortable':'large';document.documentElement.dataset.scale=uiScale;try{localStorage.setItem('daevexus.build-lab.scale',uiScale);}catch{}render();if(modal)drawModal();break;
 case 'close':closeModal();break;
 }}catch(error){toast(error.message||'This action could not be completed.');}}

// Delegated handlers survive render updates; every inserted user string is escaped.
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled)doAction(el);});
document.addEventListener('error',event=>{if(event.target.tagName==='IMG'){const target=event.target;target.parentElement.classList.add('placeholder');target.replaceWith(Object.assign(document.createElement('span'),{textContent:'◇'}));}},true);
dialog.addEventListener('cancel',event=>{event.preventDefault();closeModal();});
dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();});
document.addEventListener('submit',event=>{if(event.target.id==='rename-form'){event.preventDefault();const name=$('#variant-name').value.trim();if(name){mutate(a=>a.name=name.slice(0,80));closeModal();}}});
let textBefore=null;
document.addEventListener('focusin',event=>{const el=event.target;if(['title','notes'].includes(el.dataset?.field)||el.hasAttribute?.('data-gear-note')||el.hasAttribute?.('data-gear-plan'))textBefore={id:el.id,doc:clone(doc)};});
document.addEventListener('focusout',event=>{if(textBefore?.id!==event.target.id)return;const before=textBefore;textBefore=null;if(JSON.stringify(before.doc)!==JSON.stringify(doc)){history.push(before.doc);if(history.length>30)history.shift();future=[];document.querySelectorAll('[data-action=undo]').forEach(n=>n.disabled=false);document.querySelectorAll('[data-action=redo]').forEach(n=>n.disabled=true);}});
document.addEventListener('input',event=>{const el=event.target;
 if(el.dataset.search==='skills'){search=el.value;render();}
 if(el.dataset.search==='picker'&&modal){modal.q=el.value;modal.preview='';modal.limit=60;drawModal();dialog.querySelector('.picker-list')?.scrollTo(0,0);}
 if(el.dataset.field==='title'){doc.title=el.value.slice(0,120);doc.updatedAt=Date.now();scheduleSave();}
 if(el.dataset.field==='notes'){v().notes=el.value.slice(0,12000);doc.updatedAt=Date.now();scheduleSave();}
 if(el.hasAttribute('data-gear-note')&&modal&&v().gear[modal.slot]){v().gear[modal.slot].note=el.value.slice(0,600);doc.updatedAt=Date.now();scheduleSave();}
 if(el.hasAttribute('data-gear-plan')&&modal&&v().gear[modal.slot]){const key=el.dataset.gearPlan,limits={potential:120,substats:300,philosopherStone:180,magicstones:300};if(Object.hasOwn(limits,key)){v().gear[modal.slot][key]=el.value.slice(0,limits[key]);doc.updatedAt=Date.now();scheduleSave();}}
});
document.addEventListener('change',event=>{const el=event.target,key=el.dataset.field;
 if(key&&!['title','notes'].includes(key)){
  if(['classSlug','region'].includes(key)&&el.value!==v()[key]){if(!confirm('Changing '+(key==='region'?'region':'class')+' resets equipment, skills, collections and boards only in this variant. Continue?')){render();return;}
   const value=el.value;resetView();mutate(a=>{const keep={id:a.id,name:a.name,notes:a.notes,level:a.level,goal:a.goal,classSlug:a.classSlug,region:a.region,faction:a.faction};Object.assign(a,variant(),keep,{[key]:value});});
  }else {const value=el.value;mutate(a=>{a[key]=['level','petLevel'].includes(key)?boundedInt(value,1,100):value;if(key==='faction')a.wingId='';});}
  if(modal?.type==='character')drawModal();
 }
 if(el.hasAttribute('data-variant')){const value=el.value;if(doc.variants.some(x=>x.id===value)){resetView();mutate((a,d)=>d.activeId=value);}}
 if(el.hasAttribute('data-grade')&&modal){modal.grade=el.value;modal.preview='';modal.limit=60;drawModal();dialog.querySelector('.picker-list')?.scrollTo(0,0);}
 if(el.hasAttribute('data-preview-level')&&modal){modal.petLevel=Number(el.value);drawModal();}
 if(el.hasAttribute('data-compare')){compareId=el.value;render();}
 if(el.hasAttribute('data-board')){board=el.value;nodeFocus='';render();}
 if(el.hasAttribute('data-budget')){const value=boundedInt(el.value,0,9999);mutate(a=>a.budgets[board]=value);}
 if(el.hasAttribute('data-enchant')&&modal){const value=boundedInt(el.value,0,30);mutate(a=>a.gear[modal.slot].enchant=value);}
 if(el.hasAttribute('data-skill-range'))setSkillLevel(el.dataset.skillRange,skillLevels(cache[el.dataset.skillRange])[Number(el.value)]);
});
function inspectNode(el){if(!catalog||tab!=='daevanion')return;const node=boardNodes(v(),catalog,board).find(n=>n.id===el.dataset.id);if(!node)return;nodeFocus=node.id;const ledger=$('.board-ledger');if(ledger){ledger.querySelector('h3').textContent=node.label;ledger.querySelector('p').textContent='Reference cost: '+node.cost;}}
document.addEventListener('mouseover',event=>{const el=event.target.closest('.node');if(el)inspectNode(el);});
document.addEventListener('focusin',event=>{if(event.target.matches('.node'))inspectNode(event.target);});
$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>LIMIT)throw new Error('This JSON file is too large.');const imported=normalize(JSON.parse(await file.text()));if(!confirm('Open this imported build? The current workspace will be kept in My builds.'))return;imported.id=uid();switchDocument(imported,'Imported as an independent copy.');}catch(error){toast(error.message||'Could not import this file.');}});
window.addEventListener('keydown',event=>{
 const target=document.activeElement,editing=/INPUT|TEXTAREA|SELECT/.test(target?.tagName);
 if(target?.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const i=tabs.findIndex(x=>x[0]===tab),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tab=tabs[next][0];search='';render();$('#tab-'+tab)?.focus();return;}
 if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();saveBuild();}
 else if(!editing&&!dialog.open&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();doAction({dataset:{action:event.shiftKey?'redo':'undo'}});}
});
window.addEventListener('beforeunload',()=>{if(saveTimer&&!storageBlocked)persist();});
async function start(){try{
 const response=await fetch('/build-lab/catalog',{signal:AbortSignal.timeout(20000)});if(!response.ok)throw new Error('The reference catalog could not be loaded.');catalog=await response.json();if(!catalog.classes?.length||!Array.isArray(catalog.equipment))throw new Error('Catalog format is unavailable.');
 for(const key of ['wings','pets','arcana'])if(!Array.isArray(catalog[key]))catalog[key]=[];catalog.boards||={};
 try{const saved=localStorage.getItem(STORAGE);if(saved){doc=normalize(JSON.parse(saved));autosave='Local workspace restored';}uiScale=localStorage.getItem('daevexus.build-lab.scale')||'comfortable';}catch{storageBlocked=true;autosave='Unreadable saved draft protected';toast('A saved draft could not be read. It is preserved. Save new work to My builds or export it.');}
 document.documentElement.dataset.scale=uiScale;
 const code=new URLSearchParams(location.hash.slice(1)).get('build');if(code)try{const imported=await readShare(code);pendingPrevious=clone(doc);imported.id=uid();doc=imported;autosave='Shared copy · edit or Save to keep';window.history.replaceState(null,'',location.pathname);toast('Shared build opened as a separate copy.');}catch(error){toast(error.message||'Invalid shared build. Your local draft is unchanged.');}
 render();
 }catch(error){root.innerHTML=`<div class="boot"><span class="crest">✦</span><h1>Build Creator Lab</h1><p>${e(error.message)}</p><button id="retry-boot" class="gold">Retry catalog</button><a href="/?menu=open">Return to DAEVEXUS</a></div>`;$('#retry-boot').onclick=start;}}
start();
